#include <algorithm>
#include <iostream>

using namespace std;

bool e[201];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, mx = 0, mn = 200, c = 0;
    char a;

    cin >> n;

    for (int i = 0; i < n; i++) {
        cin >> a;
        if (a == '*') {
            e[i + 1] = true;
            mx = max(mx, i + 1);
            mn = min(mn, i + 1);
        }
    }

    for (int i = mn; i <= mx; i++) {
        if (e[i]) {
            int k = (mx - i) / 4;
            for (int y = 1; y <= k; y++) {
                for (int j = 1; j < 5; j++) {
                    if (e[i + y * j])
                        c++;
                    else
                        break;
                }

                if (c == 3) {
                    cout << "yes";
                    return 0;
                }
                c = 0;
            }
        }
    }

    cout << "no";
    return 0;
}

